// 诊断脚本（不属于判卷面）：从 tests/expected.json 反推每一级应有的常量。
// 每级形如：
//   A 型: (v + Math.floor(v / 3) + C) % 997
//   B 型: v ^ (((i + 1) * K) % M)
//   C 型: (v * 3 - D) % 991
//   D 型: (v * 2 + E) % 1000
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const stageOf = (i) => ((i - 1) % 4) + 1; // 1=A 2=B 3=C 4=D（按文件里现存的类型轮换）

const sh = (n, t) => String(n).padStart(2, "0");

// 只改一个级：把第 i 级的当前实现替换成候选实现，看能否命中 expected
async function runWith(overrides = {}, upto = 32) {
  let v = exp.input;
  const out = [];
  for (let i = 1; i <= upto; i += 1) {
    const p = new URL("../src/s" + sh(i) + ".js", import.meta.url).href + "?v=" + i + "-" + Math.random();
    if (overrides[i]) {
      await import("data:text/javascript," + encodeURIComponent(overrides[i]));
      const m = await import("data:text/javascript," + encodeURIComponent(overrides[i]));
      v = m.default(v);
    } else {
      const m = await import(p);
      v = m["step" + i](v);
    }
    out.push(v);
  }
  return out;
}

console.log("input =", exp.input);
console.log("stage types:", Array.from({ length: 32 }, (_, k) => stageOf(k + 1)).join(","));

// ---- 逐级反推常量 ----
// 对每一级，先用当前代码算出实际输出与期望输出之差，再按类型穷举常量空间。
for (let i = 1; i <= 32; i += 1) {
  const prev = i === 1 ? exp.input : exp.stages[i - 2];
  const want = exp.stages[i - 1];
  const t = stageOf(i);
  const cands = [];
  if (t === 1) {
    for (let C = -40; C <= 40; C += 1) {
      if (((prev + Math.floor(prev / 3) + C) % 997 + 997) % 997 === want) cands.push({ C });
    }
  } else if (t === 3) {
    for (let D = -60; D <= 60; D += 1) {
      if ((((prev * 3 - D) % 991) + 991) % 991 === want) cands.push({ D });
    }
  } else if (t === 4) {
    for (let E = -60; E <= 60; E += 1) {
      if (((prev * 2 + E) % 1000 + 1000) % 1000 === want) cands.push({ E });
    }
  } else {
    for (let K = 1; K <= 400; K += 1) {
      for (let M = 2; M <= 1024; M += 1) {
        if ((prev ^ (((i + 1) * K) % M)) === want) cands.push({ K, M });
      }
    }
  }
  console.log(
    "level " + sh(i) + " type " + t + " prev=" + prev + " want=" + want +
      (cands.length ? "  cands=" + JSON.stringify(cands.slice(0, 12)) : "  *** NO CANDIDATE ***")
  );
}

// 诊断脚本（不属于判卷面）：从 tests/expected.json 反推每一级应有的常量。
// 每级形如：
//   A 型 (i%4==1): (v + Math.floor(v / 3) + C) % 997   —— C = 0
//   B 型 (i%4==2): v ^ (((i + 1) * K) % M)            —— K/M 有多解，按“纯轮换”找唯一自洽解
//   C 型 (i%4==3): (v * 3 - D) % 991                  —— D = i
//   D 型 (i%4==0): (v * 2 + E) % 1000                 —— E = 1
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const stages = exp.stages;
const sh = (n) => String(n).padStart(2, "0");
const typeOf = (i) => ((i - 1) % 4) + 1;

// 收集每一级在“上一级正确值”下满足 w = v ^ (((i+1)*K) % M) 的所有 (K, M) 解。
const sols = new Map();
for (const i of [2, 6, 10, 14, 18, 22, 26, 30]) {
  const prev = stages[i - 2];
  const want = stages[i - 1];
  const xorMask = prev ^ want; // 必须等于 ((i+1)*K) % M
  const xorMask2 = want ^ prev;
  const n = i + 1;
  const list = [];
  for (let K = 1; K <= 4096; K += 1) {
    for (let M = 2; M <= 4096; M += 1) {
      if ((n * K) % M === xorMask) list.push({ K, M });
      // 也要考虑 xorMask 与 xorMask2 不同的情况（prev^want == want^prev，其实恒等）
    }
  }
  sols.set(i, list);
  console.log("level " + sh(i) + ": prev=" + prev + " want=" + want + " maskNeeded=" + xorMask + " #sols=" + list.length);
}

// 找“纯轮换”假设：K、M 全程不变（各级只有函数名/类型不同，没有级内变量）。
for (const [i, list] of sols) {
  console.log("level " + sh(i) + " first 6:", JSON.stringify(list.slice(0, 6)));
}

// 诊断脚本（不属于判卷面）：反推每一级应有的常量。
//   A 型 (i%4==1): (v + Math.floor(v / 3) + C) % 997   —— C = 0
//   B 型 (i%4==2): v ^ (((i + 1) * K) % M)            —— K/M 单级多解，需全局一致解
//   C 型 (i%4==3): (v * 3 - D) % 991                  —— D = i
//   D 型 (i%4==0): (v * 2 + E) % 1000                 —— E = 1
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const stages = exp.stages;

// ---- A / C / D 型：单解，直接反推 ----
for (let i = 1; i <= 32; i += 1) {
  const prev = i === 1 ? exp.input : stages[i - 2];
  const want = stages[i - 1];
  const t = ((i - 1) % 4) + 1;
  if (t === 1) {
    const Cs = [];
    for (let C = -2000; C <= 2000; C += 1) {
      const r = (prev + Math.floor(prev / 3) + C) % 997;
      if (r === want || r === want - 997) Cs.push(C);
    }
    console.log(`A 型 level ${i}: prev=${prev} want=${want} -> C in [${Cs.join(",")}]`);
  } else if (t === 3) {
    const Ds = [];
    for (let D = -2000; D <= 2000; D += 1) {
      const r = (prev * 3 - D) % 991;
      if (r === want || r === want - 991) Ds.push(D);
    }
    console.log(`C 型 level ${i}: prev=${prev} want=${want} -> D in [${Ds.join(",")}]`);
  } else if (t === 4) {
    const Es = [];
    for (let E = -2000; E <= 2000; E += 1) {
      const r = (prev * 2 + E) % 1000;
      if (r === want || r === want - 1000) Es.push(E);
    }
    console.log(`D 型 level ${i}: prev=${prev} want=${want} -> E in [${Es.join(",")}]`);
  }
}

// ---- B 型：求全局一致 (K, M) ----
const bIdx = [2, 6, 10, 14, 18, 22, 26, 30];
const cons = bIdx.map((i) => ({ i, n: i + 1, mask: stages[i - 2] ^ stages[i - 1] }));
console.log("B 型约束:", JSON.stringify(cons));

const hits = [];
for (let M = 2; M <= 20000; M += 1) {
  for (let K = 1; K <= 20000; K += 1) {
    let ok = true;
    for (const c of cons) {
      if (((c.n * K) % M) !== c.mask) { ok = false; break; }
    }
    if (ok) hits.push({ K, M });
    if (hits.length >= 40) break;
  }
  if (hits.length >= 40) break;
}
console.log("B 型全局一致解 (K,M) 前若干:", JSON.stringify(hits));

// 诊断脚本（不属于判卷面）：反推每一级应有的常量。
//   A 型 (i%4==1): (v + Math.floor(v / 3) + C) % 997   —— C = 0
//   B 型 (i%4==2): v ^ MASK                            —— 试探 mask 是否为常数
//   C 型 (i%4==3): (v * 3 - D) % 991                  —— D = i
//   D 型 (i%4==0): (v * 2 + E) % 1000                 —— E = 1
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const stages = exp.stages;

// ---- A / C / D 型 ----
const aRes = [], cRes = [], dRes = [];
for (let i = 1; i <= 32; i += 1) {
  const prev = i === 1 ? exp.input : stages[i - 2];
  const want = stages[i - 1];
  const t = ((i - 1) % 4) + 1;
  if (t === 1) {
    for (let C = 0; C <= 1996; C += 1) {
      if ((prev + Math.floor(prev / 3) + C) % 997 === want) { aRes.push({ i, C }); break; }
    }
  } else if (t === 3) {
    for (let D = -40; D <= 40; D += 1) {
      if (((prev * 3 - D) % 991 + 991) % 991 === want) { cRes.push({ i, D }); break; }
    }
  } else if (t === 4) {
    for (let E = -40; E <= 40; E += 1) {
      if (((prev * 2 + E) % 1000 + 1000) % 1000 === want) { eRes = E; dRes.push({ i, E }); break; }
    }
  }
}
console.log("A 型 C:", JSON.stringify(aRes));
console.log("C 型 D:", JSON.stringify(cRes));
console.log("D 型 E:", JSON.stringify(dRes));

// ---- B 型：先看每级的 mask 是否为常数 ----
const masks = [2, 6, 10, 14, 18, 22, 26, 30].map((i) => ({
  i, prev: stages[i - 2], want: stages[i - 1], mask: stages[i - 2] ^ stages[i - 1],
}));
console.log("B 型每级所需 mask:", JSON.stringify(masks));
console.log("mask 是否全等:", new Set(masks.map((m) => m.mask)).size === 1);

// ---- B 型：假设 v ^ (X % 64)，X 为每级变量，找一致的 (X公式) ----
// 已知 n = i+1 = 3,7,11,15,19,23,27,31 (步长 4)，所需 mask = 14,42,6,34,62,26,54,18
// 观察：mask / n => 14/3, 42/7=6, 6/11, 34/15 ...
// 试 mask = (n*K) % 64 在 n ≡ 3 (mod 4) 时的取值：n*K mod 64
for (let M of [16, 32, 64, 128, 256, 512, 1024]) {
  const good = [];
  for (let K = 1; K <= 4096; K += 1) {
    let ok = true;
    for (const m of masks) {
      if ((((m.i + 1) * K) % M) !== m.mask) { ok = false; break; }
    }
    if (ok) good.push(K);
  }
  console.log(`  M=${M} 一致的 K:`, JSON.stringify(good));
}

// 诊断脚本（不属于判卷面）：反推每一级应有的常量。
//   A 型 (i%4==1): (v + Math.floor(v / 3) + C) % 997   —— C = 0
//   B 型 (i%4==2): v ^ MASK                            —— 试探 mask 是否为常数
//   C 型 (i%4==3): (v * 3 - D) % 991                  —— D = i
//   D 型 (i%4==0): (v * 2 + E) % 1000                 —— E = 1
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const stages = exp.stages;

const aRes = [], cRes = [], dRes = [];
for (let i = 1; i <= 32; i += 1) {
  const prev = i === 1 ? exp.input : stages[i - 2];
  const want = stages[i - 1];
  const t = ((i - 1) % 4) + 1;
  if (t === 1) {
    for (let C = 0; C <= 1996; C += 1) {
      if ((prev + Math.floor(prev / 3) + C) % 997 === want) { aRes.push({ i, C }); break; }
    }
  } else if (t === 3) {
    for (let D = -40; D <= 40; D += 1) {
      if (((prev * 3 - D) % 991 + 991) % 991 === want) { cRes.push({ i, D }); break; }
    }
  } else if (t === 4) {
    for (let E = -40; E <= 40; E += 1) {
      if (((prev * 2 + E) % 1000 + 1000) % 1000 === want) { dRes.push({ i, E }); break; }
    }
  }
}
console.log("A 型 C:", JSON.stringify(aRes.map((r) => r.C)));
console.log("C 型 D:", JSON.stringify(cRes.map((r) => r.D)));
console.log("D 型 E:", JSON.stringify(dRes.map((r) => r.E)));

// ---- B 型所需 mask ----
const masks = [2, 6, 10, 14, 18, 22, 26, 30].map((i) => ({
  i, prev: stages[i - 2], want: stages[i - 1], mask: stages[i - 2] ^ stages[i - 1],
}));
console.log("B 型 mask:", JSON.stringify(masks.map((m) => [m.i, m.mask])));

// 假设 mask = (A*i + B) % M   —— 穷举 M, B，再由两级解出 A
const solsABM = [];
for (let M = 8; M <= 2048; M += 1) {
  for (let B = 0; B < M; B += 1) {
    const A1 = masks[1].i, r1 = (masks[1].mask - B) % M;
    // 解 A*A1 ≡ r1 (mod M)：暴力最小正 A
    let found = null;
    for (let A = 0; A < M; A += 1) {
      if ((A * A1) % M === (((r1 % M) + M) % M)) { found = A; break; }
    }
    if (found === null) continue;
    let ok = true;
    for (const m of masks) {
      if (((found * m.i + B) % M) !== m.mask) { ok = false; break; }
    }
    if (ok) solsABM.push({ A: found, B, M });
  }
}
console.log("mask=(A*i+B)%M 解数:", solsABM.length, JSON.stringify(solsABM.slice(0, 15)));

// 假设 mask = ((i+1)*K) % M（同 K 同 M），扩到 M<=65536
const solsK = [];
for (let M = 2; M <= 65536; M += 1) {
  let candidateK = -1;
  let ok = true;
  for (const m of masks) {
    let k = -1;
    for (let t = 1; t <= 4096; t += 1) {
      if (((m.i + 1) * t) % M === m.mask) { k = t; break; }
    }
    if (k === -1) { ok = false; break; }
    if (candidateK === -1) candidateK = k;
    else if (candidateK !== k) { ok = false; break; }
  }
  if (ok) solsK.push({ K: candidateK, M });
}
console.log("mask=((i+1)*K)%M 同参数解数:", solsK.length, JSON.stringify(solsK.slice(0, 15)));

// 诊断脚本（不属于判卷面）：验证反推出的常量能复现 tests/expected.json 全 32 级。
//   A 型 (i%4==1): (v + Math.floor(v / 3) + 0) % 997
//   B 型 (i%4==2): v ^ ((7 * i) % 64)
//   C 型 (i%4==3): (v * 3 - i) % 991
//   D 型 (i%4==0): (v * 2 + 1) % 1000
import { readFileSync } from "node:fs";

const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));

const fn = {
  1: (v, i) => (v + Math.floor(v / 3) + 0) % 997,
  2: (v, i) => v ^ ((7 * i) % 64),
  3: (v, i) => (v * 3 - i) % 991,
  4: (v, i) => (v * 2 + 1) % 1000,
};

let v = exp.input;
let bad = 0;
for (let i = 1; i <= 32; i += 1) {
  const t = ((i - 1) % 4) + 1;
  v = fn[t](v, i);
  const want = exp.stages[i - 1];
  const ok = v === want;
  if (!ok) bad += 1;
  console.log(`level ${String(i).padStart(2, "0")} type ${t}: got=${v} want=${want} ${ok ? "OK" : "*** MISMATCH ***"}`);
}
console.log(bad === 0 ? "ALL 32 STAGES MATCH" : `${bad} mismatches`);

