  t=$(( (i - 1) % 4 + 1 ))
  case $t in
    1) sed -i '' 's|(v + Math\.floor(v / 3) + 1) % 997|(v + Math.floor(v / 3) + 0) % 997|' "$f" ;;
    2) sed -i '' "s|v \^ (((i + 1) \* 7) % 64)|v ^ ((7 * $i) % 64)|" "$f" ;;
    3) sed -i '' "s|(v \* 3 - i + 1) % 991|(v * 3 - $i) % 991|" "$f" ;;
    4) sed -i '' 's|(v \* 2 + 2) % 1000|(v * 2 + 1) % 1000|' "$f" ;;
  esac
done
echo "=== patched files ==="
for i in $(seq 1 32); do printf 's%02d: ' $i; grep -E 'return' "src/s$(printf '%02d' $i).js"; done

